        Settings settings; CancellationTokenSource cancel; UdpClient udp; TcpListener listener; readonly JavaScriptSerializer json = new JavaScriptSerializer(); readonly object logLock = new object(); readonly object settingsLock = new object(); readonly List<string> logs = new List<string>(); Forms.NotifyIcon trayIcon; ClientEngine torrentEngine; TrackerServer torrentTracker; ITrackerListener torrentTrackerListener; TcpListener distributionMetadataListener; readonly ConcurrentDictionary<string,DistributionTask> distributionMap=new ConcurrentDictionary<string,DistributionTask>(); readonly ConcurrentDictionary<string,TorrentManager> distributionManagers=new ConcurrentDictionary<string,TorrentManager>(); readonly ConcurrentDictionary<string,ConcurrentDictionary<string,DistributionPeerStatus>> distributionPeers=new ConcurrentDictionary<string,ConcurrentDictionary<string,DistributionPeerStatus>>(); bool settingsRecoveredFromBackup; bool settingsNeedsInitialSave; string settingsLoadWarning; string settingsSaveError;
